class Solution {
  public boolean isRobotBounded(String instructions) {
    int[] place = {0, 0, 0};
    Character direct = new Character('n');
    int[] newPlace = {0, 0, 0};
    for (int i = 0; i < 4; i++) {
      newPlace = move(instructions, newPlace);
      if (place[0] == newPlace[0] && place[1] == newPlace[1]) return true;
    }
    return false;
  }

  public int[] move(String instructions, int[] start) {
    int[] newPlace = {start[0], start[1], start[2]};
    for (int i = 0; i < instructions.length(); i++) {
      char inst = instructions.charAt(i);
      if (inst == 'G') {
        if (newPlace[2] == 0) newPlace[1]++;
        else if (newPlace[2] == 2) newPlace[1]--;
        else if (newPlace[2] == 1) newPlace[0]--;
        else newPlace[0]++;
      } else if (inst == 'L') {
        if (newPlace[2] == 0) newPlace[2] = 1;
        else if (newPlace[2] == 1) newPlace[2] = 2;
        else if (newPlace[2] == 2) newPlace[2] = 3;
        else newPlace[2] = 0;
      } else {
        if (newPlace[2] == 0) newPlace[2] = 3;
        else if (newPlace[2] == 3) newPlace[2] = 2;
        else if (newPlace[2] == 2) newPlace[2] = 1;
        else newPlace[2] = 0;
      }
    }
    return newPlace;
  }
}
